const input = $input.first().json || {};
const alert = input.alert && typeof input.alert === 'object' ? input.alert : {};

let payloads = [];
if (Array.isArray(input.delivery_payloads)) {
  payloads = input.delivery_payloads;
} else if (input.ntfy_topic) {
  payloads = [input];
}

if (!payloads.length) {
  return [];
}

return payloads.map((payload) => ({
  json: {
    ...payload,
    event_action: alert.event_action || payload.event_action || '',
    alert_status: alert.status || payload.alert_status || '',
    delivery_fingerprint_version: 'v1'
  }
}));

return $input.all().map((item) => {
  const row = item.json || {};
  const payload = row.payload && typeof row.payload === 'object' ? row.payload : {};
  return {
    json: {
      ...payload,
      delivery_uuid: row.delivery_uuid || null,
      delivery_key: row.delivery_key || null,
      reservation_status: row.reservation_status || null,
      reservation_reason: row.reservation_reason || null,
      should_send: Boolean(row.should_send)
    }
  };
});

const responses = $input.all();
const reservations = $('Format Delivery Reservation').all()
  .map((item) => item.json || {})
  .filter((row) => row.should_send === true);

return responses.map((item, index) => {
  const response = item.json || {};
  const reservation = reservations[index] || {};
  const errorMessage =
    response?.error?.message ||
    response?.error ||
    (!response.sent && response.message ? response.message : null);

  return {
    json: {
      ...reservation,
      ...response,
      sent: response.sent === true,
      delivery_error: errorMessage ? String(errorMessage) : null
    }
  };
});

return $input.all().map((item) => {
  const row = item.json || {};
  return {
    json: {
      sent: false,
      suppressed: true,
      alert_id: row.alert_id || null,
      subscriber_id: row.subscriber_id || null,
      subscriber_name: row.subscriber_name || null,
      ntfy_topic: row.ntfy_topic || null,
      delivery_uuid: row.delivery_uuid || null,
      delivery_key: row.delivery_key || null,
      status: row.reservation_status || 'SUPPRESSED',
      reason: row.reservation_reason || 'Exact duplicate suppressed',
      matched_watch_ids: row.matched_watch_ids || [],
      match_reasons: row.match_reasons || []
    }
  };
});

const items = $input.all().map((item) => item.json || {});
return items.map((row) => ({
  json: {
    ...row,
    delivery_guard_result: row.suppressed
      ? 'SUPPRESSED'
      : (row.status === 'SENT' ? 'SENT' : row.status || 'UNKNOWN')
  }
}));
